newton_sys &lt;- function(F, J, x, tol = 1e-12, maxit = 50) {
  for (k in 1:maxit) {
    delta &lt;- solve(J(x), -F(x))          # one linear solve per step
    x &lt;- x + delta
    if (sqrt(sum(delta^2)) &lt; tol) return(x)
