def newton_damped(F, J, x, tol=1e-12, maxit=50):
    for k in range(1, maxit + 1):
        delta = np.linalg.solve(J(x), -F(x))
        t = 1.0
        while (np.any(x + t * delta &lt; 0) or
               np.linalg.norm(F(x + t * delta)) &gt; np.linalg.norm(F(x))):
            t = t / 2
            if t &lt; 1e-10:
                raise RuntimeError("damping failed")
