// rust/examples/newton_systems_c6.rs  —  cargo run --example newton_systems_c6
// C6: failures (nearly singular J, NaN for a non-integer Hill coefficient)
// and a damped Newton that keeps concentrations non-negative.
use nalgebra::{DMatrix, DVector};

const ALPHA: f64 = 3.0;

// the Hill coefficient n is a parameter here, so we can change it
fn f(x: &DVector&lt;f64&gt;, n: f64) -&gt; DVector&lt;f64&gt; {
    let (u, v) = (x[0], x[1]);
    DVector::from_vec(vec![ALPHA / (1.0 + v.powf(n)) - u,
                           ALPHA / (1.0 + u.powf(n)) - v])
}

fn jac(x: &DVector&lt;f64&gt;, n: f64) -&gt; DMatrix&lt;f64&gt; {
    let (u, v) = (x[0], x[1]);
    DMatrix::from_row_slice(2, 2, &[
        -1.0, -ALPHA * n * v.powf(n - 1.0) / (1.0 + v.powf(n)).powi(2),
        -ALPHA * n * u.powf(n - 1.0) / (1.0 + u.powf(n)).powi(2), -1.0])
}

// returns the path x_0, x_1, ...; None if J is exactly singular at some step
fn newton_sys(f: impl Fn(&DVector&lt;f64&gt;) -&gt; DVector&lt;f64&gt;,
              jac: impl Fn(&DVector&lt;f64&gt;) -&gt; DMatrix&lt;f64&gt;,
              x0: &DVector&lt;f64&gt;, tol: f64, maxit: usize) -&gt; Option&lt;Vec&lt;DVector&lt;f64&gt;&gt;&gt; {
    let mut x = x0.clone();
    let mut path = vec![x.clone()];
    for _ in 0..maxit {
        let delta = jac(&x).lu().solve(&(-f(&x)))?; // one linear solve per step
        x += &delta;
        path.push(x.clone());
        if delta.norm() &lt; tol {                      // norm() = sqrt(sum of squares)
            return Some(path);
        }
    }
    eprintln!("warning: no convergence");
    Some(path)
}

fn v2(a: f64, b: f64) -&gt; DVector&lt;f64&gt; { DVector::from_vec(vec![a, b]) }

fn newton_damped(n: f64, x0: &DVector&lt;f64&gt;, tol: f64, maxit: usize) -&gt; DVector&lt;f64&gt; {
    let mut x = x0.clone();
    for k in 1..=maxit {
        let delta = jac(&x, n).lu().solve(&(-f(&x, n))).expect("singular Jacobian");
        let mut t = 1.0;
        // halve the step until x stays &gt;= 0 and ||F|| does not grow
        loop {
            let xt = &x + &delta * t;
            if xt.iter().all(|&c| c &gt;= 0.0) && f(&xt, n).norm() &lt;= f(&x, n).norm() {
                break;
            }
            t /= 2.0;
            if t &lt; 1e-10 { panic!("damping failed"); }
        }
        x += &delta * t;
        println!("{} {} {:?}", k, t, x.as_slice());
        if (&delta * t).norm() &lt; tol { break; }
    }
    x
}

fn main() {
    // (a) two nearby starts
    for s in [[1.9, 0.5], [2.0, 0.55]] {
        let x0 = v2(s[0], s[1]);
        let p = newton_sys(|x: &DVector&lt;f64&gt;| f(x, 2.0), |x: &DVector&lt;f64&gt;| jac(x, 2.0), &x0, 1e-12, 50).unwrap();
        let step1 = (&p[1] - &p[0]).norm();
        let minval = p.iter().flat_map(|x| x.iter().copied()).fold(f64::INFINITY, f64::min);
        let end = p.last().unwrap();
        println!("start {:?} | det J: {:.3} | first step length: {:.3} | min u, v on the way: {:.3} | end: {:.6} {:.6}",
                 s, jac(&x0, 2.0).determinant(), step1, minval, end[0], end[1]);
    }
    // (b) Hill coefficient 2.5: plain Newton
    let mut x = v2(2.0, 0.5);
    for _ in 0..2 {
        // with NaN entries the LU still "succeeds" and returns NaN
        x += jac(&x, 2.5).lu().solve(&(-f(&x, 2.5))).unwrap();
        println!("{:?}", x.as_slice());
    }
    // (c) damped Newton
    let xd = newton_damped(2.5, &v2(2.0, 0.5), 1e-12, 50);
    println!("{:?}", f(&xd, 2.5).as_slice());
}

// Output:
// start [1.9, 0.5] | det J: -0.030 | first step length: 8.057 | min u, v on the way: -5.136 | end: 1.213412 1.213412
// start [2.0, 0.55] | det J: 0.066 | first step length: 3.424 | min u, v on the way: -0.891 | end: 2.618034 0.381966
// [9.72273233260433, -3.2462489413408573]
// [NaN, NaN]
// 1 0.125 [2.9653415415755413, 0.03171888233239284]
// 2 1 [2.9931075381195704, 0.1817681588407846]
// 3 1 [2.955241004252892, 0.18723069602320588]
// 4 1 [2.9550962475008484, 0.1873633129788433]
// 5 1 [2.9550962031489827, 0.18736332124930322]
// 6 1 [2.9550962031489827, 0.1873633212493033]
// [0.0, 0.0]




At \((1.9, 0.5)\) the Jacobian is nearly singular (\(\det J = -0.03\)), the first step has length 8 and goes to \(u = -5.1\), and the run ends in the middle state. A start only \(0.1\) away, also with small \(\det J\), ends in “U on” after a detour through \(v = -0.89\). Near the curve \(\det J = 0\) the outcome is unpredictable.
With \(n = 2.5\) the first step gives \(v = -3.25\), and \((-3.25)^{2.5}\) is NaN; every later iterate is NaN. (Python also prints a RuntimeWarning: invalid value encountered in scalar power; R and Rust are silent.)
The damped Newton halves the first step three times (\(t = 0.125\)) to stay non-negative, then takes full steps and converges quadratically to the “U on” state of the \(n = 2.5\) switch, \((2.955096, 0.187363)\). Library routines use similar safeguards: scipy’s hybr uses a trust region, and multiroot(F, c(2, 0.5), positive = TRUE) keeps the iterates non-negative and also finds \((2.955096, 0.187363)\) (without positive = TRUE it warns “steady-state not reached”).

